(()=>{const t=document.querySelector(".progress i");if(!t)return;const e=()=>{const n=document.documentElement.scrollHeight-window.innerHeight,o=n>0?Math.min(Math.max(window.scrollY/n,0),1):0;t.style.width=`${o*100}%`};window.addEventListener("scroll",e,{passive:!0}),window.addEventListener("resize",e),e()})();
